<script setup lang="ts">
import { nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { researchApi } from '../api/research'
import { accessSession } from '../stores/access'
import { downloadBlob } from '../utils/csv'
import { taskName } from '../utils/biologyLocale'
import type { ResearchKind, ResearchResult, ResearchSelection, ResearchFinding } from '../types/research'
const props=defineProps<{kind:ResearchKind;recordId:string;selection?:ResearchSelection;completed:boolean}>()
const emit=defineEmits<{loaded:[result:ResearchResult|null]}>()
const result=ref<ResearchResult|null>(null), findings=ref<ResearchFinding[]>([]), error=ref(''), busy=ref(false), saving=ref(false), note=ref(''), refresh=ref(0)
const drawer=ref<HTMLDialogElement|null>(null), editor=ref<HTMLDialogElement|null>(null)
let action:AbortController|undefined
watch([()=>props.kind,()=>props.recordId,()=>props.completed,refresh],async(_v,_o,cleanup)=>{
 const control=new AbortController();cleanup(()=>control.abort());action?.abort();saving.value=false;busy.value=false;error.value='';result.value=null;findings.value=[];note.value='';drawer.value?.close();editor.value?.close()
 emit('loaded',null)
 if(!props.recordId)return
 const identity=props.recordId
 const responses=await Promise.allSettled([researchApi.result(props.kind,identity,control.signal),accessSession.value?.read_only?Promise.resolve({items:[]}):researchApi.findings(props.kind,identity,control.signal)])
 if(control.signal.aborted||props.recordId!==identity)return
 if(responses[0].status==='fulfilled'){result.value=responses[0].value;emit('loaded',result.value)}
 else error.value=responses[0].reason instanceof Error?responses[0].reason.message:'来源记录读取失败'
 if(responses[1].status==='fulfilled')findings.value=responses[1].value.items
 else if(!error.value)error.value='研究笔记读取失败，请重试；已有结果仍可查看。'
},{immediate:true})
async function save(){
 if(saving.value||busy.value||!note.value.trim()||!props.completed)return
 const control=action=new AbortController(),kind=props.kind,id=props.recordId,selection={...props.selection};saving.value=true;error.value=''
 try{const item=await researchApi.save(kind,id,selection,note.value.trim(),control.signal);if(!control.signal.aborted&&id===props.recordId){findings.value=[item,...findings.value];note.value='';editor.value?.close();await nextTick();drawer.value?.showModal()}}
 catch(e){if(!control.signal.aborted)error.value=e instanceof Error?e.message:'保存失败，请重试'}finally{if(action===control)saving.value=false}
}
async function exportRecord(){
 if(busy.value||saving.value)return
 const control=action=new AbortController(),id=props.recordId;busy.value=true;error.value=''
 try{const data=await researchApi.export(props.kind,id,control.signal);if(!control.signal.aborted&&props.recordId===id)downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`${id}_research.json`)}
 catch(e){if(!control.signal.aborted)error.value=e instanceof Error?e.message:'研究记录导出失败'}finally{if(action===control)busy.value=false}
}
function value(v:unknown){return v==null?'未提供':typeof v==='string'?v:JSON.stringify(v)}
const unitLabels:Record<string,string>={expression:'表达量尺度',delta:'组间变化尺度',function:'功能支持评分尺度'}
const availabilityLabels:Record<string,string>={expression:'表达响应',function:'功能支持证据',projection:'细胞表达投影',comparison:'模型与实测诊断',export:'研究记录导出'}
const layerLabels:Record<string,string>={expression:'表达响应',function:'功能证据',coverage:'数据覆盖',structure:'细胞结构示意'}
const groupLabels:Record<string,string>={control:'实测对照',predicted:'模型预测',observed:'扰动实测'}
function sourceLabel(kind:string){return ({measured:'实测数据',prediction:'模型预测',synthetic_demo:'合成演示'} as Record<string,string>)[kind]??`未识别来源（${kind}）`}
onBeforeUnmount(()=>action?.abort())
</script>
<template>
 <div class="research-evidence-actions"><button class="btn btn-sm" @click="drawer?.showModal()">来源与证据 <span class="evidence-count">笔记 {{findings.length}}</span></button><button v-if="!accessSession?.read_only" class="btn btn-sm" :disabled="!completed||busy" @click="editor?.showModal()">保存发现</button><button class="btn btn-sm" :disabled="busy||saving||!completed" @click="exportRecord">{{busy?'正在整理…':'研究记录 · JSON'}}</button></div>
 <p v-if="error" class="evidence-error" role="alert">{{error}} <button class="btn btn-sm" @click="refresh++">重新读取</button></p>
 <dialog ref="drawer" class="research-evidence-drawer" @click="e=>{if(e.target===drawer)drawer?.close()}"><header><div><span class="eyebrow">EVIDENCE EXPLORER</span><h2>来源、方法与研究发现</h2></div><button class="btn btn-sm" aria-label="关闭证据抽屉" @click="drawer?.close()">关闭</button></header><div class="evidence-body">
 <p class="evidence-id">{{kind==='measured'?'实测分析':'模型响应'}} · {{recordId}}</p><p v-if="error" role="alert">{{error}}</p><template v-if="result"><section><h3>研究上下文</h3><dl><dt>细胞背景</dt><dd>{{result.background.cell_line}}</dd><dt>扰动目标</dt><dd>{{result.target.perturbation}}</dd><dt>来源类型</dt><dd>{{sourceLabel(result.source_kind)}}</dd><dt>当前证据层</dt><dd>{{selection?.layer?layerLabels[selection.layer]:'未选择'}}</dd><dt>投影方法</dt><dd>{{selection?.projection_id?.toUpperCase()||'未选择'}}</dd><dt>所选群体</dt><dd>{{selection?.group_id?groupLabels[selection.group_id]:'全部 / 未限定'}}</dd><dt>选中基因</dt><dd>{{selection?.gene_id||'未选择'}}</dd><dt>{{selection?.layer==='function'?'选中任务':'保留的任务上下文'}}</dt><dd>{{selection?.task_id?taskName(selection.task_id):'未选择'}}<small v-if="selection?.task_id&&taskName(selection.task_id)!==selection.task_id" class="raw-task-id">{{selection.task_id}}</small></dd><template v-for="(v,k) in result.units" :key="k"><dt>{{unitLabels[k]||k}}</dt><dd>{{v||'未提供'}}</dd></template></dl></section>
 <section><h3>群体口径</h3><p class="population-label">原运行群体</p><div class="population-list"><span v-for="item in result.populations?.original.groups||result.groups" :key="item.id">{{groupLabels[item.id]||item.id}} <strong>{{item.count==null?'未记录':item.count.toLocaleString('zh-CN')}}</strong></span></div><template v-if="result.populations?.matched_comparison"><p class="population-label">匹配实测诊断群体</p><div v-if="result.populations.matched_comparison.availability.available" class="population-list"><span v-for="item in result.populations.matched_comparison.groups" :key="item.id">{{groupLabels[item.id]||item.id}} <strong>{{item.count==null?'未记录':item.count.toLocaleString('zh-CN')}}</strong></span></div><p v-else class="muted">{{result.populations.matched_comparison.availability.reason}}</p><template v-if="result.populations.matched_comparison.availability.available"><p class="muted">匹配后的群体另列；它不替换原运行群体，也不能当作独立留出验证。</p><p v-if="result.populations.matched_comparison.batch_sensitivity?.baseline_conclusion_consistent===false" class="evidence-caution">基线结论依赖批次权重，请查看实验对照中的敏感性诊断。</p><details><summary>匹配比较的独立指纹</summary><p class="fingerprint">{{result.populations.matched_comparison.provenance?.comparison_sha256}}</p></details><RouterLink :to="{path:'/runs/'+recordId,query:{tab:'comparison'}}" @click="drawer?.close()">查看完整实验对照 →</RouterLink></template></template></section>
 <section><h3>数据与方法指纹</h3><p class="fingerprint">{{result.provenance.manifest_sha256||'历史结果未提供可核验的 manifest 指纹'}}</p><details><summary>完整来源记录</summary><dl><template v-for="(v,k) in result.provenance" :key="k"><dt>{{k}}</dt><dd>{{value(v)}}</dd></template></dl></details></section>
 <section><h3>可用结果</h3><div v-for="(v,k) in result.availability" :key="k" class="availability-row"><span>{{availabilityLabels[k]||k}}</span><strong>{{v.available?'已提供':'不可用'}}</strong><p v-if="v.reason">{{v.reason}}</p><p v-if="k==='comparison'&&kind==='measured'">本页「实验对照」展示实测对照组与扰动组的描述性比较。</p></div></section><section v-if="result.warnings.length||result.limitations.length"><h3>解释范围</h3><ul><li v-for="line in [...result.warnings,...result.limitations]" :key="line">{{line}}</li></ul></section></template>
 <section><h3>已保存的发现 <span>{{findings.length}}</span></h3><p v-if="!findings.length" class="muted">尚未保存研究笔记。保存时会绑定当前结果与选择条件。</p><article v-for="f in findings" :key="f.id" class="finding-item"><p>{{f.note}}</p><small>{{f.selection.gene_id||(f.selection.task_id?taskName(f.selection.task_id):'研究总览')}}<template v-if="f.selection.projection_id"> · {{f.selection.projection_id.toUpperCase()}} · {{f.selection.group_id?groupLabels[f.selection.group_id]:'全部群体'}}</template> · {{new Date(f.created_at).toLocaleString('zh-CN')}}</small><code>{{f.manifest_sha256?.slice(0,16)||'无清单指纹'}}</code></article></section></div></dialog>
 <dialog ref="editor" class="finding-editor"><form @submit.prevent="save"><header><div><span class="eyebrow">RESEARCH NOTEBOOK</span><h2>保存一条研究发现</h2></div><button type="button" class="btn btn-sm" @click="editor?.close()">关闭</button></header><div class="evidence-body"><p class="evidence-id">{{recordId}}</p><p>{{selection?.gene_id||'未选基因'}} · {{selection?.task_id?taskName(selection.task_id):'未选任务'}}</p><p v-if="selection?.projection_id">{{selection.projection_id.toUpperCase()}} · {{selection.group_id?groupLabels[selection.group_id]:'全部群体'}}</p><label for="finding-note">研究笔记</label><textarea id="finding-note" v-model="note" rows="6" maxlength="4000" placeholder="记录发现、证据限制，以及需要进一步验证的问题" required/><p class="muted">笔记与结果指纹、选择条件保存在研究数据库中，不改写原始结果。</p><p v-if="error" role="alert">{{error}}</p></div><footer><button type="button" class="btn" @click="editor?.close()">取消</button><button type="submit" class="btn btn-primary" :disabled="saving||!note.trim()">{{saving?'正在保存…':'保存发现'}}</button></footer></form></dialog>
</template>
<style scoped>
.research-evidence-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.evidence-count{padding:1px 5px;background:var(--primary-weak);border-radius:5px;margin-left:5px}.raw-task-id{display:block;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.population-label{font-weight:600;margin:15px 0 8px}.population-list{display:flex;flex-wrap:wrap;gap:9px 18px;padding:12px;background:var(--surface-soft);border-radius:8px}.population-list strong{color:var(--primary-strong);margin-left:6px}.evidence-caution{border-left:3px solid var(--gold);padding-left:10px;color:var(--ink)}.evidence-error{font-size:12px;color:var(--danger);line-height:1.8}.research-evidence-drawer{position:fixed;margin:0 0 0 auto;inset:0;width:500px;max-width:96vw;height:100dvh;max-height:100dvh;border:0;border-left:1px solid var(--border);padding:0;color:var(--ink);background:var(--card);box-shadow:-12px 0 60px #163e2a30}.research-evidence-drawer::backdrop,.finding-editor::backdrop{background:#133f2c65;backdrop-filter:blur(3px)}header{padding:25px;display:flex;gap:20px;justify-content:space-between;align-items:start;border-bottom:1px solid var(--border)}h2{font-size:21px;font-weight:500;margin:10px 0 0}h3{font-size:14px;font-weight:600;margin:0 0 17px}.eyebrow{font-size:10px;color:var(--muted);letter-spacing:1.5px}.evidence-body{padding:0 25px 25px;font-size:12px;line-height:1.9}.evidence-body section{padding:22px 0;border-top:1px solid var(--border)}.evidence-id{font:11px Consolas,monospace;color:var(--muted);overflow-wrap:anywhere;margin:20px 0}.evidence-body dl{display:grid;grid-template-columns:120px 1fr;gap:12px}.evidence-body dt{color:var(--muted);overflow-wrap:anywhere}.evidence-body dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.fingerprint{padding:13px;background:var(--surface-soft);font:11px/1.8 Consolas,monospace;overflow-wrap:anywhere}.availability-row{display:flex;gap:12px;flex-wrap:wrap;padding:10px 0;border-bottom:1px solid var(--border)}.availability-row strong{margin-left:auto;font-weight:500;color:var(--primary)}.availability-row p{flex-basis:100%;color:var(--muted);margin:0}.finding-item{padding:16px;background:var(--surface-soft);border:1px solid var(--border);border-radius:10px;margin:10px 0}.finding-item p{white-space:pre-wrap;overflow-wrap:anywhere;margin:0 0 10px}.finding-item small,.finding-item code{font-size:10px;display:block;color:var(--muted)}.finding-editor{width:650px;max-width:94vw;padding:0;border:1px solid var(--border);border-radius:18px;background:var(--card);color:var(--ink)}textarea{display:block;width:100%;font:inherit;line-height:1.8;border:1px solid var(--border);border-radius:9px;padding:14px;background:var(--surface-soft);color:var(--ink);margin-top:10px;resize:vertical}footer{padding:18px 25px;background:var(--surface-soft);display:flex;justify-content:flex-end;gap:10px}.finding-editor .muted{font-size:11px}summary{cursor:pointer;color:var(--primary)}.evidence-body ul{padding-left:20px;color:var(--muted)}
</style>
